  \vspace{0.5cm}

  \textbf{Contexts:}
  \begin{itemize}
    \item \textbf{Lab context:} Controlled laboratory setting (original)
    \item \textbf{Field context:} Applied real-world setting (generalization test)
  \end{itemize}

  \vspace{0.5cm}

  \textbf{Measures:}
  \begin{itemize}
    \item Primary outcome Y (same as Studies 1-2)
    \item Mediators A and B
